// Native-only storage ABI. Actual addresses are written and consumed on the
// GPU; JavaScript sees only the browser's opaque resource objects. A logical
// renderer buffer can exceed the browser's per-shared-allocation size limit.
template<class T> struct OmwPaged {
    const unsigned long long* pages;
    T* direct;
    unsigned long long first;
    __device__ OmwPaged(const unsigned long long* table):pages(table),direct(nullptr),first(0) {}
    __device__ OmwPaged(T* pointer):pages(nullptr),direct(pointer),first(0) {}
    template<class U> __device__ OmwPaged(const OmwPaged<U>& other):pages(other.pages),direct(other.direct),first(other.first) {}
    __device__ T& operator[](unsigned long long index) const {
        index+=first;
        if(direct)return direct[index];
        unsigned long long bytes=index*sizeof(T);
        return *reinterpret_cast<T*>(pages[bytes>>26]+(bytes&67108863ull));
    }
    __device__ OmwPaged operator+(unsigned long long offset) const {
        OmwPaged result=*this;result.first+=offset;return result;
    }
};

// Bounds and bilinear text colors stay on the GPU. One disjoint glyph group
// per invocation; no CPU bounds reduction or vertex-color interpolation.
__global__ void shade_text_gradient(const unsigned long long* omw_pages_vertices,const unsigned long long* omw_pages_ranges,const unsigned long long* omw_pages_colors,unsigned int range_count) {
OmwPaged<float> vertices(omw_pages_vertices);
OmwPaged<const unsigned int> ranges(omw_pages_ranges);
OmwPaged<const float> colors(omw_pages_colors);

    unsigned int r=(blockIdx.x+blockIdx.y*gridDim.x)*blockDim.x+threadIdx.x;
    if(r>=range_count)return;
    unsigned int first=ranges[r*3u],count=ranges[r*3u+1u],p=ranges[r*3u+2u]*16u;
    if(count==0u)return;
    float minx=3.402823466e38f,miny=3.402823466e38f,maxx=1.175494351e-38f,maxy=1.175494351e-38f;
    for(unsigned int n=0;n<count;n++) {
        unsigned int v=(first+n)*10u;
        minx=fminf(minx,vertices[v]);maxx=fmaxf(maxx,vertices[v]);
        miny=fminf(miny,vertices[v+1u]);maxy=fmaxf(maxy,vertices[v+1u]);
    }
    for(unsigned int n=0;n<count;n++) {
        unsigned int v=(first+n)*10u;
        float x=maxx!=minx?(vertices[v]-minx)/(maxx-minx):0.0f;
        float y=maxy!=miny?(vertices[v+1u]-miny)/(maxy-miny):0.0f;
        for(unsigned int k=0;k<4;k++) {
            float left=colors[p+4u+k]*(1.0f-y)+colors[p+k]*y;
            float right=colors[p+8u+k]*(1.0f-y)+colors[p+12u+k]*y;
            vertices[v+4u+k]=left*(1.0f-x)+right*x;
        }
    }
}
